// src/components/AttendancePage.js

import React, { useState } from 'react';
// import './AttendanceTab.css';  // Import the CSS for styling

const AttendanceTab = () => {
  const [employeeId, setEmployeeId] = useState('');
 

  // Handle form input change
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    if (name === 'employeeId') {
      setEmployeeId(value);
    } 
  };

  // Handle form submit
  const handleSubmit = (e) => {
    e.preventDefault();
    alert(`Attendance recorded for Employee ID: ${employeeId}`);
    // Here you would typically send the data to the backend for saving
    setEmployeeId('');
  };

  return (
    <div className="attendance-page">
      <h2 className="attendance-header">Employee Attendance</h2>

      {/* Map Emoji */}
      <div className="attendance-logo">
        <span role="img" aria-label="Location" className="map-emoji">🗺️</span>
      </div>

      {/* Attendance Form */}
      <form onSubmit={handleSubmit} className="attendance-form">
        <div className="form-group">
          <label htmlFor="employeeId">Employee ID:</label>
          <input
            type="text"
            id="employeeId"
            name="employeeId"
            value={employeeId}
            onChange={handleInputChange}
            required
          />
        </div>

        
        <button type="submit" className="submit-btn">Record Attendance</button>
      </form>
    </div>
  );
};

export default AttendanceTab;
